"""Self-contained visual kit for polished, offline prototype pages."""

THEMES = ("aurora", "clean-light", "midnight-gold", "fresh-green", "sunset", "mono-pro")

# Components available to generated markup: nav navigation; hero headline area; btn/btn-ghost actions;
# section and section-title content blocks; grid-2/grid-3 layouts; card elevated panels; icon-badge icon tile;
# stat-row/stat sample metrics; steps ordered process; pricing offer cards; faq details; phone app mockup;
# dashboard admin shell; table data; badge labels; cta conversion block; footer page ending; reveal visual accent.
ALLOWED_CLASSES = frozenset({
    "nav", "hero", "btn", "btn-ghost", "section", "section-title", "grid-3", "grid-2",
    "card", "icon-badge", "stat-row", "stat", "steps", "pricing", "faq", "phone",
    "dashboard", "table", "badge", "cta", "footer", "reveal", "sample", "chart",
})

_VARS = {
    "aurora": "--bg:#0d1023;--surface:#171a35;--surface-2:#202448;--text:#f7f7ff;--muted:#c1c5dd;--primary:#9b8cff;--accent:#54e4d1;--ring:#b7aaff;--radius:24px;--shadow:0 24px 70px #03041488;--grad-1:#5e45d8;--grad-2:#16a6b8",
    "clean-light": "--bg:#f4f7fc;--surface:#ffffff;--surface-2:#eaf0fb;--text:#18223a;--muted:#53627b;--primary:#315eea;--accent:#08706c;--ring:#315eea;--radius:20px;--shadow:0 18px 52px #233e681c;--grad-1:#b9d5ff;--grad-2:#d9d0ff",
    "midnight-gold": "--bg:#11100e;--surface:#1d1b18;--surface-2:#29251e;--text:#fffaf0;--muted:#d0c8b7;--primary:#e7bd67;--accent:#f5dfaa;--ring:#f0cb75;--radius:18px;--shadow:0 24px 70px #0009;--grad-1:#5b4219;--grad-2:#2d2740",
    "fresh-green": "--bg:#eff7f1;--surface:#ffffff;--surface-2:#e1f1e6;--text:#163628;--muted:#496859;--primary:#16734d;--accent:#26744a;--ring:#16734d;--radius:22px;--shadow:0 18px 50px #174e321b;--grad-1:#c6edcf;--grad-2:#e0f2b6",
    "sunset": "--bg:#fff5ef;--surface:#ffffff;--surface-2:#ffebe1;--text:#3c2030;--muted:#705260;--primary:#b83d64;--accent:#9d3c25;--ring:#b83d64;--radius:24px;--shadow:0 20px 55px #73374b20;--grad-1:#ffc39c;--grad-2:#f4b9d0",
    "mono-pro": "--bg:#f5f5f3;--surface:#ffffff;--surface-2:#e9e9e6;--text:#171717;--muted:#555653;--primary:#191919;--accent:#50594f;--ring:#242424;--radius:12px;--shadow:0 18px 48px #11111118;--grad-1:#d7d9d4;--grad-2:#bcc5bb",
}

_CSS = r"""
*{box-sizing:border-box}html{scroll-behavior:smooth}body{margin:0;background:var(--bg);color:var(--text);font:400 16px/1.65 system-ui,"Segoe UI",Tahoma,Arial,sans-serif}a{color:inherit;text-decoration:none}button{font:inherit}img,svg{max-width:100%}.site{width:min(1160px,100% - 40px);margin-inline:auto}.nav{position:sticky;top:12px;z-index:5;display:flex;align-items:center;justify-content:space-between;gap:16px;margin:14px auto;padding:12px 18px;border:1px solid color-mix(in srgb,var(--text) 12%,transparent);border-radius:999px;background:color-mix(in srgb,var(--surface) 84%,transparent);backdrop-filter:blur(18px);box-shadow:var(--shadow)}
.hero{position:relative;isolation:isolate;overflow:hidden;min-height:510px;display:grid;align-content:center;gap:24px;padding:clamp(32px,7vw,88px);border:1px solid color-mix(in srgb,var(--text) 9%,transparent);border-radius:calc(var(--radius)*1.4);background:linear-gradient(135deg,color-mix(in srgb,var(--grad-1) 38%,var(--surface)),var(--surface) 58%,color-mix(in srgb,var(--grad-2) 23%,var(--surface)));box-shadow:var(--shadow)}.hero:before,.hero:after{content:"";position:absolute;z-index:-1;width:clamp(180px,35vw,420px);aspect-ratio:1;border-radius:50%;filter:blur(55px);opacity:.32;animation:float 9s ease-in-out infinite alternate;background:var(--primary);inset-block-start:-18%;inset-inline-end:-8%}.hero:after{inset-block:auto -30%;inset-inline:auto 35%;background:var(--accent);animation-delay:-4s}.hero h1{max-width:850px;margin:0;font-size:clamp(2.7rem,7vw,6rem);line-height:1.02;letter-spacing:-.055em}.hero h1 strong,.hero .keyword{background:linear-gradient(100deg,var(--primary),var(--accent));color:transparent;background-clip:text}.hero p{max-width:650px;color:var(--muted);font-size:clamp(1.05rem,2vw,1.25rem)}.btn{display:inline-flex;align-items:center;justify-content:center;min-height:48px;padding:12px 22px;border:1px solid var(--primary);border-radius:999px;background:var(--primary);color:var(--bg);font-weight:750;transition:transform .2s,box-shadow .2s}.btn-ghost{background:transparent;color:var(--text);border-color:color-mix(in srgb,var(--text) 25%,transparent)}.btn:hover,.card:hover{transform:translateY(-4px);box-shadow:var(--shadow)}a:focus-visible,button:focus-visible,summary:focus-visible{outline:3px solid var(--ring);outline-offset:4px}.section{padding-block:clamp(52px,8vw,100px)}.section-title{max-width:760px;margin:0 0 28px;font-size:clamp(1.9rem,4vw,3.4rem);line-height:1.12;letter-spacing:-.035em}.grid-2,.grid-3{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:18px}.grid-3{grid-template-columns:repeat(3,minmax(0,1fr))}.card{padding:clamp(20px,3vw,32px);border:1px solid color-mix(in srgb,var(--text) 10%,transparent);border-radius:var(--radius);background:var(--surface);box-shadow:var(--shadow);transition:transform .22s,box-shadow .22s}.icon-badge,.badge{display:inline-grid;place-items:center;min-width:42px;min-height:42px;padding:8px;border-radius:14px;background:color-mix(in srgb,var(--primary) 16%,var(--surface));color:var(--primary);font-weight:750}.badge{min-width:0;min-height:0;border-radius:999px}.stat-row{display:grid;grid-template-columns:repeat(3,1fr);gap:12px}.stat{padding:20px;border-radius:var(--radius);background:var(--surface-2)}.sample{display:inline-block;margin-block-start:8px;padding:2px 8px;border-radius:99px;background:var(--surface);color:var(--muted);font-size:.72rem}.steps{display:grid;gap:14px;counter-reset:step}.steps>*{position:relative;padding:20px 64px 20px 20px;border-radius:var(--radius);background:var(--surface);counter-increment:step}.steps>*:before{content:counter(step,decimal-leading-zero);position:absolute;inset-inline-start:20px;color:var(--primary);font-weight:800}.pricing{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:16px}.faq details{padding:18px 0;border-bottom:1px solid color-mix(in srgb,var(--text) 15%,transparent)}.faq summary{cursor:pointer;font-weight:750}.phone{width:min(310px,100%);margin-inline:auto;padding:12px;border:7px solid var(--text);border-radius:42px;background:var(--surface);box-shadow:var(--shadow)}.phone>*{padding:14px;border-radius:18px;background:var(--surface-2);margin-block:8px}.dashboard{display:grid;grid-template-columns:190px 1fr;gap:14px;padding:18px;border:1px solid color-mix(in srgb,var(--text) 12%,transparent);border-radius:var(--radius);background:var(--surface);box-shadow:var(--shadow)}.dashboard aside,.dashboard header{padding:16px;border-radius:14px;background:var(--surface-2)}.dashboard main{min-width:0}.table{width:100%;border-collapse:collapse}.table th,.table td{padding:12px;border-bottom:1px solid color-mix(in srgb,var(--text) 14%,transparent);text-align:start}.cta{padding:clamp(28px,5vw,60px);border-radius:calc(var(--radius)*1.2);background:linear-gradient(120deg,var(--grad-1),var(--grad-2));color:var(--text)}.footer{padding:30px 0;color:var(--muted);font-size:.85rem}.reveal{animation:rise .75s both}.footer-note{opacity:.72}.chart{width:100%;height:auto}.chart path{fill:none;stroke:var(--primary);stroke-width:4;stroke-linecap:round;stroke-linejoin:round}@keyframes rise{from{opacity:0;transform:translateY(16px)}to{opacity:1;transform:none}}@keyframes float{to{transform:translate(-12%,16%) scale(1.1)}}@keyframes shift{to{background-position:100% 50%}}@media(max-width:760px){.site{width:min(100% - 28px,600px)}.hero{min-height:440px;padding:28px}.grid-3,.pricing{grid-template-columns:1fr}.grid-2{grid-template-columns:1fr}.stat-row{grid-template-columns:1fr}.dashboard{grid-template-columns:1fr}.dashboard aside{display:flex;gap:10px;overflow:auto}.nav{top:6px}.table{font-size:.84rem}.table th,.table td{padding:8px 5px}}@media(prefers-reduced-motion:reduce){*,*:before,*:after{scroll-behavior:auto!important;animation-duration:.01ms!important;animation-iteration-count:1!important;transition-duration:.01ms!important}}@media print{body{background:white;color:#111}.nav{position:static;box-shadow:none}.hero,.card,.dashboard{box-shadow:none;break-inside:avoid}.hero:before,.hero:after{display:none}.btn{border:1px solid #333;background:white;color:#111}}
"""

_CSS += ".reveal{opacity:1}.reveal.is-visible{animation:rise .75s both}"
_CSS += ".cta{background:linear-gradient(120deg,var(--primary),color-mix(in srgb,var(--primary) 72%,var(--accent)));color:var(--bg)}"


def normalize_theme(theme: str | None, fallback: str = "aurora") -> str:
    return theme if theme in THEMES else (fallback if fallback in THEMES else "aurora")


def build_page(theme: str, body_html: str, title: str, rtl: bool) -> str:
    theme = normalize_theme(theme)
    lang = "ar" if rtl else "en"
    direction = "rtl" if rtl else "ltr"
    safe_title = str(title or "Prototype").replace("&", "&amp;").replace("<", "&lt;").replace(">", "&gt;")
    script = "<script>if('IntersectionObserver'in window&&!matchMedia('(prefers-reduced-motion: reduce)').matches){const o=new IntersectionObserver(es=>es.forEach(e=>{if(e.isIntersecting){e.target.classList.add('is-visible');o.unobserve(e.target)}}));document.querySelectorAll('.reveal').forEach(e=>o.observe(e))}</script>"
    # Content is expected to have passed prototype.validate_fragment before assembly.
    return f'<!doctype html><html lang="{lang}" dir="{direction}"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="color-scheme" content="light dark"><title>{safe_title}</title><style>:root{{{_VARS[theme]}}}{_CSS}</style></head><body><div class="site">{body_html}<footer class="footer footer-note">Prototype - concept design only</footer></div>{script}</body></html>'
